"""FastAPI app: POST /api/chat runs the agent; / serves the frontend."""

import logging
import os
from pathlib import Path
from typing import Literal

from dotenv import load_dotenv

ROOT = Path(__file__).resolve().parents[2]
load_dotenv(ROOT / ".env")  # must run before the agent/openai client is created

from fastapi import FastAPI, HTTPException  # noqa: E402
from fastapi.middleware.cors import CORSMiddleware  # noqa: E402
from fastapi.staticfiles import StaticFiles  # noqa: E402
from openai import APIStatusError, AuthenticationError  # noqa: E402
from pydantic import BaseModel  # noqa: E402

from .agent import run_agent  # noqa: E402

log = logging.getLogger("uvicorn.error")

app = FastAPI(title="EHL Finale Agent")
app.add_middleware(  # lets a separately served frontend (e.g. Vite on :5173) call us
    CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"]
)


class ChatTurn(BaseModel):
    role: Literal["user", "assistant"]
    content: str


class ChatRequest(BaseModel):
    message: str
    history: list[ChatTurn] = []


class ChatResponse(BaseModel):
    reply: str
    tool_calls: list[str]


@app.get("/api/health")
def health():
    return {"ok": True, "openai_key_set": bool(os.getenv("OPENAI_API_KEY"))}


@app.post("/api/chat", response_model=ChatResponse)
async def chat(req: ChatRequest):
    if not os.getenv("OPENAI_API_KEY"):
        raise HTTPException(500, "OPENAI_API_KEY is not set. Copy .env.example to .env and add your key.")
    try:
        return await run_agent(req.message, [t.model_dump() for t in req.history])
    except AuthenticationError:
        raise HTTPException(401, "OpenAI rejected the API key (check OPENAI_API_KEY in .env).")
    except APIStatusError as e:
        raise HTTPException(502, f"OpenAI API error {e.status_code}: {e.message}")
    except Exception as e:
        log.exception("agent run failed")
        raise HTTPException(500, f"Agent error: {type(e).__name__}: {e}")


# Serve the frontend at / (keep this last so /api routes win)
app.mount("/", StaticFiles(directory=ROOT / "frontend", html=True), name="frontend")

// Same origin when served by FastAPI; set to "http://localhost:8000" if you serve the frontend elsewhere.
const API_BASE = "";

const messagesEl = document.getElementById("messages");
const form = document.getElementById("chat-form");
const input = document.getElementById("input");
const statusEl = document.getElementById("status");
const history = []; // [{role, content}] sent back so the agent keeps context

function addMessage(role, text, meta) {
  const div = document.createElement("div");
  div.className = `msg ${role}`;
  div.textContent = text;
  if (meta) {
    const m = document.createElement("div");
    m.className = "meta";
    m.textContent = meta;
    div.appendChild(m);
  }
  messagesEl.appendChild(div);
  messagesEl.scrollTop = messagesEl.scrollHeight;
  return div;
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();
  const message = input.value.trim();
  if (!message) return;
  input.value = "";
  addMessage("user", message);
  const pending = addMessage("assistant", "thinking…");
  form.querySelector("button").disabled = true;

  try {
    const res = await fetch(`${API_BASE}/api/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ message, history }),
    });
    const data = await res.json();
    pending.remove();
    if (!res.ok) {
      addMessage("error", data.detail || `HTTP ${res.status}`);
      return;
    }
    const meta = data.tool_calls.length ? `tools: ${data.tool_calls.join(", ")}` : "";
    addMessage("assistant", data.reply, meta);
    history.push({ role: "user", content: message }, { role: "assistant", content: data.reply });
  } catch (err) {
    pending.remove();
    addMessage("error", `Request failed: ${err}`);
  } finally {
    form.querySelector("button").disabled = false;
    input.focus();
  }
});

fetch(`${API_BASE}/api/health`)
  .then((r) => r.json())
  .then((d) => (statusEl.textContent = d.openai_key_set ? "backend ok" : "backend ok · OPENAI_API_KEY missing"))
  .catch(() => (statusEl.textContent = "backend unreachable"));

